import pytest
from conftest import APIHelper

@pytest.mark.parametrize("username, password, expected_status", [
    ("valid_user", "valid_pass", 200),
    ("invalid_user", "invalid_pass", 400),
    ("", "valid_pass", 400),
    ("valid_user", "", 400),
])
def test_user_login(api_client, username, password, expected_status):
    """
    Test the /v2/user/login endpoint with various username and password combinations.
    """
    endpoint = "v2/user/login"
    params = {
        "username": username,
        "password": password
    }
    response = api_client.make_request(endpoint, params=params, method='GET')
    
    assert response.status_code == expected_status
    
    if response.status_code == 200:
        assert "X-Expires-After" in response.headers
        assert "X-Rate-Limit" in response.headers
        assert isinstance(response.json(), str)
    elif response.status_code == 400:
        assert response.json() == "Invalid username/password supplied"

@pytest.mark.parametrize("auth_token, expected_status", [
    ("valid_token", 200),
    ("invalid_token", 401),
    (None, 401),
])
def test_user_login_authentication(api_client, auth_token, expected_status):
    """
    Test the /v2/user/login endpoint with various authentication tokens.
    """
    endpoint = "v2/user/login"
    params = {
        "username": "valid_user",
        "password": "valid_pass"
    }
    headers = {
        "Authorization": f"Bearer {auth_token}" if auth_token else None
    }
    response = api_client.make_request(endpoint, params=params, headers=headers, method='GET')
    
    assert response.status_code == expected_status

    if response.status_code == 200:
        assert "X-Expires-After" in response.headers
        assert "X-Rate-Limit" in response.headers
        assert isinstance(response.json(), str)

